import React, { useState, useRef, useEffect } from "react";
import Image from "next/image";
import Idea from "@/public/icons/idea.svg";
import Business from "@/public/icons/business.svg";
import BusinessLogo from "@/public/icons/business-logo.svg";

const ChatUI = () => {
  const [messages, setMessages] = useState([]);
  const [inputValue, setInputValue] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const [showInitialContent, setShowInitialContent] = useState(true);
  const messagesEndRef = useRef(null);

  // Dummy chat messages for demonstration
  const dummyMessages = [
    {
      type: "user",
      content: "I want a logo for my business"
    },
    {
      type: "ai",
      content: "I'd be happy to help you create a logo for your business! To get started, I'll need some information about your business to develop a concept that represents your brand effectively.\n\nCould you share:\n1. Your business name\n2. The industry or type of business\n3. Any specific colours, symbols, or elements you'd like to include\n4. The overall feeling or impression you want your logo to convey\n5. Where you plan to use the logo (website, social media, signage, etc.)\n\nWith these details, I can help design an SVG logo that will work well across different platforms and sizes. I can provide you with the code that you can then use or further refine with a graphic designer."
    },
    {
      type: "user",
      content: "Lorem ipsum dolor sit amet consectetur. Ac consectetur sit a amet malesuada vitae. Sed aliquet gravida non amet vestibulum massa a lectus. Nec feugiat ante scelerisque pretium posuere. Habitant suscipit tristique massa consectetur euismod nunc gravida sit."
    }
  ];

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!inputValue.trim()) return;

    // Add user message
    const userMessage = { type: "user", content: inputValue };
    setMessages(prev => [...prev, userMessage]);
    
    // Clear input and hide initial content
    setInputValue("");
    setShowInitialContent(false);
    setIsLoading(true);

    // Simulate AI response after a short delay
    setTimeout(() => {
      const aiResponse = { 
        type: "ai", 
        content: "I'd be happy to help you create a logo for your business! To get started, I'll need some information about your business to develop a concept that represents your brand effectively.\n\nCould you share:\n1. Your business name\n2. The industry or type of business\n3. Any specific colours, symbols, or elements you'd like to include\n4. The overall feeling or impression you want your logo to convey\n5. Where you plan to use the logo (website, social media, signage, etc.)\n\nWith these details, I can help design an SVG logo that will work well across different platforms and sizes. I can provide you with the code that you can then use or further refine with a graphic designer."
      };
      setMessages(prev => [...prev, aiResponse]);
      setIsLoading(false);
    }, 1000);
  };

  // Auto scroll to bottom on new messages
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  // For demonstration purposes, add dummy messages
  const showDummyChat = () => {
    setMessages(dummyMessages);
    setShowInitialContent(false);
  };

  return (
    <div className="min-h-screen bg-black text-white flex flex-col">
      {/* Main Content */}
      <div className="flex-1 flex flex-col px-4 py-8 max-w-4xl mx-auto w-full">
        {/* Chat Area */}
        <div className="flex-1 mb-4 overflow-y-auto">
          {showInitialContent ? (
            <div className="text-center mb-16">
              <h1 className="text-3xl md:text-4xl mb-6">
                Harness the power of AI. Describe a logo, business or even a document
              </h1>

              <div className="mt-16">
                <h2 className="text-sm mb-1 text-left w-full text-gray-300">What would you like to create today</h2>

                {/* Feature Cards */}
                <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mt-2">
                  {/* PRD Card */}
                  <div className="bg-gray-800 bg-opacity-50 p-6 rounded-lg border border-gray-700 text-left">
                    <div className="bg-gray-700 w-10 h-10 rounded-md flex items-center justify-center mb-4">
                      <div className="w-6 h-6 text-white">💡</div>
                    </div>
                    <h3 className="font-bold text-white mb-2">Get a PRD for Your Idea</h3>
                    <p className="text-gray-400 text-sm">
                      Turn your startup idea into a structured PRD in seconds!
                    </p>
                  </div>

                  {/* Name Card */}
                  <div className="bg-gray-800 bg-opacity-50 p-6 rounded-lg border border-gray-700 text-left">
                    <div className="bg-gray-700 w-10 h-10 rounded-md flex items-center justify-center mb-4">
                      <div className="w-6 h-6 text-white">🏢</div>
                    </div>
                    <h3 className="font-bold text-white mb-2">Get a name for your business</h3>
                    <p className="text-gray-400 text-sm">
                      Find the perfect name for your startup.
                    </p>
                  </div>

                  {/* Logo Card */}
                  <div className="bg-gray-800 bg-opacity-50 p-6 rounded-lg border border-gray-700 text-left">
                    <div className="bg-gray-700 w-10 h-10 rounded-md flex items-center justify-center mb-4">
                      <div className="w-6 h-6 text-white">🎨</div>
                    </div>
                    <h3 className="font-bold text-white mb-2">Get a Logo for your business</h3>
                    <p className="text-gray-400 text-sm">
                      Describe your business, and we'll generate logo ideas!
                    </p>
                  </div>
                </div>
                
                {/* Preview dummy chat button */}
                <button 
                  onClick={showDummyChat} 
                  className="mt-8 py-2 px-4 bg-gray-700 rounded-lg text-white hover:bg-gray-600 transition-colors"
                >
                  Preview Chat Demo
                </button>
              </div>
            </div>
          ) : (
            <div className="space-y-6">
              {messages.map((message, index) => (
                <div key={index} className={`flex ${message.type === "user" ? "justify-end" : "justify-start"}`}>
                  <div 
                    className={`max-w-3xl rounded-lg p-4 ${
                      message.type === "user" 
                        ? "bg-gray-700 text-white" 
                        : "bg-gray-800 text-white border border-gray-700"
                    }`}
                    style={{ maxWidth: "80%" }}
                  >
                    <div className="whitespace-pre-line">{message.content}</div>
                  </div>
                </div>
              ))}
              {isLoading && (
                <div className="flex justify-start">
                  <div className="max-w-3xl rounded-lg p-4 bg-gray-800 text-white border border-gray-700">
                    <div className="flex space-x-2">
                      <div className="w-2 h-2 bg-gray-300 rounded-full animate-pulse"></div>
                      <div className="w-2 h-2 bg-gray-300 rounded-full animate-pulse delay-75"></div>
                      <div className="w-2 h-2 bg-gray-300 rounded-full animate-pulse delay-150"></div>
                    </div>
                  </div>
                </div>
              )}
              <div ref={messagesEndRef} />
            </div>
          )}
        </div>

        {/* Input Area */}
        <div className="mt-auto">
          <form onSubmit={handleSubmit} className="relative">
            <input
              type="text"
              value={inputValue}
              onChange={(e) => setInputValue(e.target.value)}
              placeholder="Type something..."
              className="w-full py-4 px-6 rounded-full bg-gray-800 text-white border border-gray-700 focus:outline-none focus:ring-2 focus:ring-gray-600"
              disabled={isLoading}
            />
            <button
              type="submit"
              className="absolute right-2 top-1/2 transform -translate-y-1/2 p-2 rounded-full bg-gray-700 hover:bg-gray-600 focus:outline-none"
              disabled={isLoading || !inputValue.trim()}
            >
              <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                <line x1="22" y1="2" x2="11" y2="13"></line>
                <polygon points="22 2 15 22 11 13 2 9 22 2"></polygon>
              </svg>
            </button>
          </form>

          {/* Powered by section */}
          <div className="mt-4 text-center text-gray-400 text-sm">
            Powered by <span className="font-bold">AI</span>venture studio
          </div>
        </div>
      </div>
    </div>
  );
};

export default ChatUI;